 h.update(|v|{v.sources=sources;v.dependencies=dependencies.into_values().collect();v.phase=health::Phase::Restoring;});
 let t=telemetry::Telemetry::new(&cfg.health.telemetry,&incarnation,Arc::downgrade(&h))?;
 if cfg.health.stdout{if callbacks.on_heartbeat.is_none(){callbacks.on_heartbeat=Some(Box::new(|s|{println!("{}",json!({"state":"heartbeat","health":s}));Ok(())}));}if callbacks.on_dependencies_update.is_none(){callbacks.on_dependencies_update=Some(Box::new(|d|{println!("{}",json!({"state":"dependencies","dependencies":d}));Ok(())}));}}
 let management=management::Management::start(h.clone(),t.clone(),token.clone())?;let reporter=health::Reporter::start(h.clone(),callbacks,t.clone());let mut obs=Observability{h:h.clone(),t:t.clone(),management:Some(management),reporter:Some(reporter),finished:false};
 let evolving=cfg.sources.iter().any(|s|s.evolution.is_some());
 let expanded=catalog.topics().any(|(_,s)|s.definition().format==3);
 let fingerprints=catalog.topics().map(|(name,s)|(name.to_string(),s.fingerprint().to_string())).collect::<BTreeMap<_,_>>();
 let source_limits=cfg.sources.iter().map(|s|(s.topic.clone(),s.max_rows)).collect::<BTreeMap<_,_>>();
 let max_rows=cfg.sources.iter().map(|s|s.max_rows).max().unwrap();let runtime=Runtime::new(catalog.clone(),max_rows)?;let mut owner=Owner::new(runtime,limits)?;
 let mut owners=Owners::launch_observed(cfg.sources.clone(),catalog,h.clone(),t.clone())?;
 let mut ready_sources=BTreeSet::new();let mut cuts=BTreeMap::<String,Value>::new();let mut bootstrapped=BTreeSet::new();let mut sequences=BTreeMap::new();let mut derived=BTreeMap::<String,BTreeMap<u32,u64>>::new();
 let mut complete=crate::complete::Complete::default();
