   let Some(bytes)=incoming else{continue};let value=match v13_codec_experiment::generic::decode(&bytes){Ok(v)=>v,Err(_)=>{p.dead=true;continue}};
   if !p.authenticated{let caps=value["capabilities"].as_array();if value["type"]!="hello"||value["v"]!=15||value["token"].as_str()!=Some(&token)||value["nonce"].as_str().is_none_or(|n|n.len()!=32||!n.bytes().all(|b|b.is_ascii_hexdigit()))||value["catalog"]!=json!(fingerprints)||caps.is_none_or(|c|c.len()>12||evolving&&!c.iter().any(|v|v=="schema_evolution_v1")||expanded&&!c.iter().any(|v|v=="schema_expansion_v1")||!c.iter().any(|v|v=="generic_schemas_v1")){p.dead=true;continue}p.patches_allowed=caps.unwrap().iter().any(|v|v=="selected_field_patches_v1");if p.patches_allowed{owner.allow_field_patches(id);}p.authenticated=true;p.nonce=value["nonce"].as_str().unwrap().into();p.join_allowed=caps.unwrap().iter().any(|v|v=="bounded_joins_v1");p.global_having_allowed=caps.unwrap().iter().any(|v|v=="global_having_v1");p.text_allowed=caps.unwrap().iter().any(|v|v=="text_predicates_v1");p.grouped_allowed=caps.unwrap().iter().any(|v|v=="grouped_aggregates_v1");p.health_allowed=caps.unwrap().iter().any(|v|v=="health_v1");p.trace_allowed=caps.unwrap().iter().any(|v|v=="trace_v1");enqueue(p,envelope(&incarnation,id,p,json!({"type":"ready","coverage":[0],"catalog":fingerprints,"limits":limits,"capabilities":{"generic_schemas_v1":true,"complete_source_v1":true,"effect_semantics_v1":true,"selected_field_patches_v1":p.patches_allowed,"schema_expansion_v1":true,"schema_evolution_v1":evolving,"grouped_aggregates_v1":p.grouped_allowed,"text_predicates_v1":p.text_allowed,"bounded_joins_v1":p.join_allowed,"global_having_v1":p.global_having_allowed,"health_v1":p.health_allowed,"trace_v1":p.trace_allowed}})),limits.per_client);continue}
   if value["v"]!=15||value["nonce"]!=p.nonce||value["incarnation"]!=incarnation||value["connection"]!=id.to_string(){p.dead=true;continue}
