   if let Ok(r)=&r{let dependencies=owner.dependencies(id,r);let known=dependencies.iter().all(|d|fingerprints.contains_key(d));if known{for dependency in &dependencies{owners.guard_topic(dependency)?;}}if h.stopping(){break}let snapshot=h.snapshot();let retention_ready=dependencies.is_subset(&ready_sources)&&dependencies.iter().all(|topic|snapshot.sources.iter().find(|s|&s.topic==topic).is_some_and(|s|!s.retention.enabled||s.retention.safe&&!s.retention.pending_due));result=if !known{Err("unknown configured join/source dependency".into())}else if !r.join_output_within_source_limit(&source_limits){Err("join output exceeds configured left source ceiling".into())}else if !p.join_allowed&&r.requires_join(){Err("join capability not negotiated".into())}else if !p.global_having_allowed&&r.requires_global_having(){Err("global/HAVING capability not negotiated".into())}else if !p.text_allowed&&r.requires_text(){Err("text predicate capability not negotiated".into())}else if raw["command"]["query"].get("group_by").is_some()&&!p.grouped_allowed{Err("grouped capability not negotiated".into())}else if !retention_ready&&!matches!(&r.command,crate::generic_owner::Command::Close{..}){Err("retention maintenance pending".into())}else{owner.command(id,r)};if owner.runtime.terminal(){return Err("terminal generic evaluator failure".into())}}

